func RunMigrationsTxn(db *sql.DB, migrations []Migration) error {
  tx, err := db.Begin()
  if err != nil { return err }
  for _, m := range migrations { if err := tx.Exec(m.SQL); err != nil { tx.Rollback(); return err } }
  return tx.Commit()
}
